using System;
using Cysharp.Threading.Tasks;
using DG.Tweening;
using UnityEngine;

namespace DogGuns_Games.vamsir
{
    public class Normal_Mob : VamserMobBase
    {
        [Header("<color=green>플레이어 무기")] 
        private Weaphon_base player_Weaphon;

        //피격 물체가 발사체인지 구분
        private bool _isHitByShoot;

        [Header("몹 스탯")]
        [SerializeField] private float initialHp = 100f;
        [SerializeField] private float initialSpeed = 1f;
        [SerializeField] private float initialAttackDamage = 10f;
        [SerializeField] private float initialAttackSpeed = 1f;
        [SerializeField] private float initialAttackRange = 1f;
        [SerializeField] private float initialStunTime = 0.1f;

        private void Awake()
        {
            DOTween.SetTweensCapacity(500, 50);
        }

        private void Start()
        {
            // Init() 호출을 SetTarget으로 이동하여 player 참조가 보장되도록 합니다.
        }

        private void Init()
        {
            if (player != null)
            {
                player_Weaphon = player.WeaphonBase;
                if (player_Weaphon != null)
                {
                    _isHitByShoot = player_Weaphon.isShooting;
                }
            }

            Mob_Hp = initialHp;
            Mob_Speed = initialSpeed;
            Mob_AttackDamage = initialAttackDamage;
            Mob_AttackSpeed = initialAttackSpeed;
            Mob_AttackRange = initialAttackRange;
            Mob_StunTime = initialStunTime;

            Mob_IsDie = false;
            Mob_IsHit = false;
        }

        public override void SetTarget(PlayerBase target)
        {
            base.SetTarget(target);
            Init();
        }

        public override void OnEnable()
        {
            base.OnEnable();
            // Init() 호출을 SetTarget으로 이동하여 player 참조가 보장되도록 합니다.
            SetMobState(MobState.Move);
        }


        private void FixedUpdate()
        {
            if (!ismove || player == null) // player가 null이면 이동 로직을 실행하지 않습니다.
            {
                if (ismove) transform.DOKill();
                return;
            }

            // 플레이어를 추적하는 로직
            Vector3 direction = (player.transform.position - transform.position).normalized;
            transform.position += direction * Mob_Speed * Time.fixedDeltaTime;

            // 플레이어 방향으로 몹 회전 (좌우 반전)
            if (direction.x != 0)
            {
                // direction.x > 0 이면 오른쪽을 보도록 180도 회전 (스프라이트가 왼쪽을 보고 있을 경우)
                // direction.x < 0 이면 왼쪽을 보도록 0도 회전
                float yRotation = direction.x > 0 ? 180f : 0f;
                transform.rotation = Quaternion.Euler(0, yRotation, 0);
            }
        }

        private void OnCollisionEnter2D(Collision2D other)
        {
            if (_isHitByShoot)
            {
                HandleCollision(other);
            }
        }

        private void OnCollisionStay2D(Collision2D other)
        {
            if (!_isHitByShoot)
            {
                HandleCollision(other);
            }
        }

        private void HandleCollision(Collision2D other)
        {
            if (!Mob_IsHit && other.gameObject.CompareTag("Player_Attack"))
            {
                HitCooltime(other).Forget();
                Debug.Log("_isHitByShoot: "+_isHitByShoot);
            }
        }

        private async UniTask HitCooltime(Collision2D other)
        {
            Mob_IsHit = true;

            float attackPower = player_Weaphon.attackPower;
            float stunTime = player_Weaphon.mobStunTime;

            await UniTask.Yield();
            Mob_Hp -= attackPower;

            if (Mob_Hp <= 0)
            {
                SetMobState(MobState.Die);
            }
            else
            {
                Mob_StunTime = stunTime;
                SetMobState(MobState.Stun);
            }

            Mob_IsHit = false;
        }

        protected override void Mob_Idle()
        {
        //    Debug.Log("Idle");
        }

        protected override void Mob_Move()
        {
            ismove = true;
        }

        protected override void Mob_Stun()
        {
         //   Debug.Log("Stun");

            ismove = false;

            DOVirtual.DelayedCall(Mob_StunTime, () => { SetMobState(MobState.Move); });
        }

        protected override void Mob_hit()
        {
            base.Mob_hit();
        }

        protected override void Mob_Attack()
        {
        //    Debug.Log("Attack");
        }

        protected override void Mob_Die()
        {
            base.Mob_Die();
            transform.DOKill();
        //    Debug.Log("Die");
        }
    }
}

using System;
using Cysharp.Threading.Tasks;
using DG.Tweening;
using UnityEngine;

namespace DogGuns_Games.vamsir
{
    public class Normal_Mob : VamserMobBase
    {
        [Header("<color=green>플레이어 무기")] 
        private Weaphon_base player_Weaphon;

        //피격 물체가 발사체인지 구분
        private bool _isHitByShoot;

        [Header("몹 스탯")]
        [SerializeField] private float initialHp = 100f;
        [SerializeField] private float initialSpeed = 1f;
        [SerializeField] private float initialAttackDamage = 10f;
        [SerializeField] private float initialAttackSpeed = 1f;
        [SerializeField] private float initialAttackRange = 1f;
        [SerializeField] private float initialStunTime = 0.1f;

        private void Awake()
        {
            DOTween.SetTweensCapacity(500, 50);
        }

        private void Start()
        {
            // Init() 호출을 SetTarget으로 이동하여 player 참조가 보장되도록 합니다.
        }

        private void Init()
        {
            if (player != null)
            {
                player_Weaphon = player.WeaphonBase;
                if (player_Weaphon != null)
                {
                    _isHitByShoot = player_Weaphon.isShooting;
                }
            }

            Mob_Hp = initialHp;
            Mob_Speed = initialSpeed;
            Mob_AttackDamage = initialAttackDamage;
            Mob_AttackSpeed = initialAttackSpeed;
            Mob_AttackRange = initialAttackRange;
            Mob_StunTime = initialStunTime;

            Mob_IsDie = false;
            Mob_IsHit = false;
        }

        public override void SetTarget(PlayerBase target)
        {
            base.SetTarget(target);
            Init();
        }

        public override void OnEnable()
        {
            base.OnEnable();
            // Init() 호출을 SetTarget으로 이동하여 player 참조가 보장되도록 합니다.
            SetMobState(MobState.Move);
        }


        private void FixedUpdate()
        {
            if (!ismove || player == null) // player가 null이면 이동 로직을 실행하지 않습니다.
            {
                if (ismove) transform.DOKill();
                return;
            }

            // 플레이어를 추적하는 로직
            Vector3 direction = (player.transform.position - transform.position).normalized;
            transform.position += direction * Mob_Speed * Time.fixedDeltaTime;

            // 플레이어 방향으로 몹 회전 (좌우 반전)
            if (direction.x != 0)
            {
                // direction.x > 0 이면 오른쪽을 보도록 180도 회전 (스프라이트가 왼쪽을 보고 있을 경우)
                // direction.x < 0 이면 왼쪽을 보도록 0도 회전
                float yRotation = direction.x > 0 ? 180f : 0f;
                transform.rotation = Quaternion.Euler(0, yRotation, 0);
            }
        }

        private void OnCollisionEnter2D(Collision2D other)
        {
            if (_isHitByShoot)
            {
                HandleCollision(other);
            }
        }

        private void OnCollisionStay2D(Collision2D other)
        {
            if (!_isHitByShoot)
            {
                HandleCollision(other);
            }
        }

        private void HandleCollision(Collision2D other)
        {
            if (!Mob_IsHit && other.gameObject.CompareTag("Player_Attack"))
            {
                HitCooltime(other).Forget();
                LogManager.Log("_isHitByShoot: "+_isHitByShoot);
            }
        }

        private async UniTask HitCooltime(Collision2D other)
        {
            Mob_IsHit = true;

            float attackPower = player_Weaphon.attackPower;
            float stunTime = player_Weaphon.mobStunTime;

            await UniTask.Yield();
            Mob_Hp -= attackPower;

            if (Mob_Hp <= 0)
            {
                SetMobState(MobState.Die);
            }
            else
            {
                Mob_StunTime = stunTime;
                SetMobState(MobState.Stun);
            }

            Mob_IsHit = false;
        }

        protected override void Mob_Idle()
        {
            LogManager.Log("Idle", LogManager.LogCategory.MobManager);
        }

        protected override void Mob_Move()
        {
            ismove = true;
        }

        protected override void Mob_Stun()
        {
            LogManager.Log("Stun", LogManager.LogCategory.MobManager);
            ismove = false;
            DOVirtual.DelayedCall(Mob_StunTime, () => { SetMobState(MobState.Move); });
        }

        protected override void Mob_hit()
        {
            base.Mob_hit();
        }

        protected override void Mob_Attack()
        {
            LogManager.Log("Attack");
        }

        protected override void Mob_Die()
        {
            base.Mob_Die();
            transform.DOKill();
            LogManager.Log("Die");
        }
    }
}

using Cysharp.Threading.Tasks;
using DG.Tweening;
using TMPro;
using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.ResourceManagement.AsyncOperations;

namespace DogGuns_Games.vamsir
{
    /// <summary>
    /// 뱀서라이크 게임의 기본 게임플레이 관리자
    /// </summary>
    public class VamserLikeGameManager : MonoBehaviour
    {

        #region 필드 및 변수

        [hideInInspector]
        public PlayerBase spawnedPlayer;

        [Header("캐릭터 및 무기가 스폰 될시 부모 오브젝트")]
        [SerializeField] private GameObject inGameObjectParent;

        private readonly Vector3 _spawnPosition = Vector3.zero;

        [Header("옵션 팝업 매니저")]
        [SerializeField] private OptionPopupManager optionPopupManager;

        private ObjectPoolSpawner _objectPoolSpawner;
        private VamPlayerControll _vamPlayerControll;
        #endregion

        #region Unity 라이프사이클

        /// <summary>
        /// 컴포넌트 초기화 및 이벤트 구독
        /// </summary>
        /// <summary>
        /// 컴포넌트 초기화 및 이벤트 구독
        /// </summary>
        private void Awake()
        {
            _objectPoolSpawner = FindFirstObjectByType<ObjectPoolSpawner>();
            _vamPlayerControll = FindFirstObjectByType<VamPlayerControll>();

            PlayStateManager.OnGameStart += GameStart;
            PlayStateManager.OnGamePause += Pause;
            PlayStateManager.OnGameResume += Resume;
            PlayStateManager.OnGameOver += OnGameOver;
        }

        /// <summary>
        /// 이벤트 구독 해제
        /// </summary>
        private void OnDestroy()
        {
            PlayStateManager.OnGameStart -= GameStart;
            PlayStateManager.OnGamePause -= Pause;
            PlayStateManager.OnGameResume -= Resume;
            PlayStateManager.OnGameOver -= OnGameOver;
        }


        #endregion

        #region 게임 상태 관리

        /// <summary>
        /// 게임 시작 이벤트 처리 (비동기로 변경)
        /// </summary>
        private async void GameStart()
        {
            PlayStateManager.instance.isPlay = true;
            PlayerDataManagerDontdesytoy.Instance.scritpableobjPlayerData.nowPlayMObkillCOunt = 0;

            SoundManager.PlaySound(Sound.BGM, SoundKeys.InGame, true);
            // 플레이어와 무기 스폰이 완료될 때까지 기다립니다.

            await SpawnPlayer();

            // 플레이어 스폰이 성공적으로 완료된 후에 몹 스포너를 활성화합니다.
            if (spawnedPlayer != null && _objectPoolSpawner != null)
            {
                await _objectPoolSpawner.InitializeAndStartSpawning(spawnedPlayer);
                LogManager.Log("게임 시작: 플레이어 스폰 완료 후 몹 스포너 활성화", LogManager.LogCategory.VamserLikeGameManager);
            }
            else
            {
                LogManager.LogError("플레이어 스폰에 실패했거나 ObjectPoolSpawner를 찾을 수 없어 게임을 시작할 수 없습니다.");
            }
        }

        /// <summary>
        /// 게임 일시정지 이벤트 처리
        /// </summary>
        private void Pause()
        {
            PlayStateManager.instance.isPlay = false;
            LogManager.Log("게임 일시정지", LogManager.LogCategory.VamserLikeGameManager);
        }

        /// <summary>
        /// 게임 재개 이벤트 처리
        /// </summary>
        private void Resume()
        {
            PlayStateManager.instance.isPlay = true;
            LogManager.Log("게임 재개", LogManager.LogCategory.VamserLikeGameManager);
        }

        private async void OnGameOver()
        {
            PlayStateManager.instance.isPlay = false;

            spawnedPlayer = null; // 게임 오버 시 플레이어 참조 초기화

            // 게임 내에 획득한 코인 합산
            var playerData = PlayerDataManagerDontdesytoy.Instance?.scritpableobjPlayerData;
            if (playerData != null)
            {
                playerData.currency1 += playerData.ingameCoin; // ingameCoin을 totalCoin에 합산
                playerData.ingameCoin = 0; // 인게임 코인 초기화
                LogManager.Log($"게임 오버: 코인 합산 완료 (총 코인: {playerData.currency1})", LogManager.LogCategory.VamserLikeGameManager);

                // 서버 업로드는 반드시 메인 스레드에서 실행
                await UniTask.SwitchToMainThread();
                var param = new BackEnd.Param();
                param.Add("Money1", playerData.currency1);
                ServerManager.Instance.UploadData("User_Data", param, bro =>
                {
                    if (bro.IsSuccess())
                    {
                        LogManager.Log("서버에 코인 데이터 업로드 성공", LogManager.LogCategory.VamserLikeGameManager);
                    }
                    else
                    {
                        LogManager.LogError($"서버에 코인 데이터 업로드 실패: {bro}", LogManager.LogCategory.VamserLikeGameManager);
                    }
                });
            }
            else
            {
                LogManager.LogWarning("PlayerDataManagerDontdesytoy 또는 scritpableobjPlayerData가 null입니다. 코인 합산 실패", LogManager.LogCategory.VamserLikeGameManager);
            }

            LogManager.Log("게임 오버", LogManager.LogCategory.VamserLikeGameManager);
        }

        /// <summary>
        /// 메뉴 팝업 열기와 게임 상태 변경
        /// </summary>
        public void Open_MenuPopUp(bool isPause)
        {
            PlayStateManager.instance.PlayState = isPause ? 
                PlayStateManager.GameState.Pause : 
                PlayStateManager.GameState.Resume;

            LogManager.Log($"메뉴 팝업 {(isPause ? "열림" : "닫힘")}", LogManager.LogCategory.VamserLikeGameManager);
        }

        /// <summary>
        /// 옵션 팝업 열기
        /// </summary>
        public void Open_OptionPopUp()
        {
            if (optionPopupManager == null)
            {
                LogManager.LogError("옵션 팝업 매니저가 설정되지 않았습니다.", LogManager.LogCategory.VamserLikeGameManager);
                return;
            }

            Instantiate(optionPopupManager);
            optionPopupManager.gameObject.SetActive(true);
            LogManager.Log("옵션 팝업 열림", LogManager.LogCategory.VamserLikeGameManager);
        }

        #endregion

        #region 플레이어/무기 스폰 관리


        /// <summary>
        /// 현재 선택된 플레이어와 무기를 비동기적으로 스폰합니다. (반환 타입을 UniTask로 변경)
        /// </summary>
        private async UniTask SpawnPlayer()
        {
            if (!PlayStateManager.instance.isPlay || inGameObjectParent == null)
            {
                LogManager.LogWarning("게임이 플레이 상태가 아니거나 부모 오브젝트가 설정되지 않았습니다.", LogManager.LogCategory.VamserLikeGameManager);
                return;
            }

            try
            {
                Weaphon_base spawnedWeapon = await SpawnSelectedWeapon();
                if (spawnedWeapon == null)
                {
                    LogManager.LogError("무기 스폰에 실패하여 캐릭터를 스폰할 수 없습니다.", LogManager.LogCategory.VamserLikeGameManager);
                    return;
                }

                await SpawnSelectedCharacter(spawnedWeapon);
            }
            catch (System.Exception ex)
            {
                LogManager.LogError($"플레이어 또는 무기 스폰 중 예외 발생: {ex.Message}", LogManager.LogCategory.VamserLikeGameManager);
                spawnedPlayer = null; // 실패 시 참조를 null로 설정
            }
        }

        /// <summary>
        /// 선택된 무기를 Addressable을 사용하여 스폰합니다.
        /// </summary>
        private async UniTask<Weaphon_base> SpawnSelectedWeapon()
        {
            int weaponIndex = PlayerDataManagerDontdesytoy.Instance.SelectWeaponIndex;
            string addressableKey = $"Weapon_{weaponIndex}"; // ��기 Addressable 주소 규칙

            try
            {
                GameObject weaponInstance = await Addressables.InstantiateAsync(addressableKey, _spawnPosition, Quaternion.identity, inGameObjectParent.transform).ToUniTask();
                if (weaponInstance != null)
                {
                    LogManager.Log($"무기 스폰 성공: {addressableKey}", LogManager.LogCategory.VamserLikeGameManager);
                    return weaponInstance.GetComponent<Weaphon_base>();
                }
                return null;
            }
            catch (System.Exception ex)
            {
                LogManager.LogError($"Addressable 키 '{addressableKey}'를 가진 무기 스폰 중 예외 발생: {ex.Message}", LogManager.LogCategory.VamserLikeGameManager);
                return null;
            }
        }

        /// <summary>
        /// 선택된 캐릭터를 스폰하고 무기를 설정합니다.
        /// </summary>
        private async UniTask SpawnSelectedCharacter(Weaphon_base weaponToAssign)
        {
            int characterIndex = PlayerDataManagerDontdesytoy.Instance.SelectCharacterIndex;
            string addressableKey = $"Player_Character_{characterIndex}";

            try
            {
                GameObject characterInstance = await Addressables.InstantiateAsync(addressableKey, _spawnPosition, Quaternion.identity, inGameObjectParent.transform).ToUniTask();
                if (characterInstance != null)
                {
                    LogManager.Log($"캐릭터 스폰 성공: {addressableKey}", LogManager.LogCategory.VamserLikeGameManager);
                    spawnedPlayer = characterInstance.GetComponent<PlayerBase>();
                    if (spawnedPlayer != null)
                    {
                        spawnedPlayer.InitializeWeapon(weaponToAssign);
                        if (_vamPlayerControll != null)
                        {
                            _vamPlayerControll.AssignCharacter(spawnedPlayer);
                        }
                        else
                        {
                            LogManager.LogError("VamPlayerControll을 찾을 수 없습니다.", LogManager.LogCategory.VamserLikeGameManager);
                        }
                    }
                    else
                    {
                        LogManager.LogError("스폰된 캐릭터에서 PlayerBase 컴포넌트를 찾을 수 없습니다.", LogManager.LogCategory.VamserLikeGameManager);
                    }
                }
            }
            catch (System.Exception ex)
            {
                LogManager.LogError($"Addressable 키 '{addressableKey}'를 가진 캐릭터 스폰 중 예외 발생: {ex.Message}", LogManager.LogCategory.VamserLikeGameManager);
                // 실패 시 _spawnedPlayer를 null로 설정
                spawnedPlayer = null;
            }
        }


        /// <summary>
        /// 현재 스폰된 캐릭터와 무기를 변경
        /// </summary>
        public async void ChangeCharacterAndWeapon_Spawn()
        {
            if (inGameObjectParent == null)
            {
                LogManager.LogError("인게임 오브젝트 부모가 설정되지 않았습니다.", LogManager.LogCategory.VamserLikeGameManager);
                return;
            }

            // 현재 캐릭터와 무기 제거
            for (int i = inGameObjectParent.transform.childCount - 1; i >= 0; i--)
            {
                Transform child = inGameObjectParent.transform.GetChild(i);
                // Addressables로 생성된 오브젝트는 Addressables.ReleaseInstance로 해제��는 것이 좋습니다.
                Addressables.ReleaseInstance(child.gameObject);
            }
            spawnedPlayer = null; // 참조 제거

            // 새 캐릭터와 무기 스폰 (비동기 호출 및 대기)
            await SpawnPlayer();
            LogManager.Log("캐릭터와 무기 변경 완료", LogManager.LogCategory.VamserLikeGameManager);
        }

        #endregion

        #region UI 효과 및 데이터 접근

        /// <summary>
        /// 웨이브 텍스트에 페이드 효과 적용
        /// </summary>
        public void WaveTextFadeEffect(TMP_Text mobWaveText)
        {
            if (mobWaveText == null)
            {
                LogManager.LogError("웨이브 텍스트가 null입니다.", LogManager.LogCategory.VamserLikeGameManager);
                return;
            }

            // 페이드 인 효과
            mobWaveText.DOFade(1, 1)
                .SetEase(Ease.Linear)
                .OnComplete(() =>
                {
                    // 페이드 아웃 효과
                    mobWaveText.DOFade(0, 1)
                        .SetEase(Ease.Linear)
                        .SetDelay(1f);
                });
        }

        /// <summary>
        /// 현재 처치한 몹 수 반환
        /// </summary>
        public int Mob_Count()
        {
            return PlayerDataManagerDontdesytoy.Instance?.scritpableobjPlayerData?.nowPlayMObkillCOunt ?? 0;
        }

        /// <summary>
        /// 현재 몹 스폰 웨이브 반환
        /// </summary>
        public int MobSpawnWave()
        {
            return _objectPoolSpawner?.MobSpawnWave ?? 0;
        }


        /// <summary>
        /// 현재 플레이어 레벨 반환
        /// </summary>
        public float PlayerLevel()
        {
