            LogManager.LogWarning("스폰된 플레이어가 없어 레벨을 가져올 수 없습니다.", LogManager.LogCategory.VamserLikeGameManager);
            return 1; // 기본값 반환
        }

        /// <summary>
        /// 현재 플레이어의 경험치 반환
        /// </summary>
