        {
            if (spawnedPlayer != null)
            {
                return spawnedPlayer.CurrentExp;
            }

            return 0f;
        }

        /// <summary>
        /// 현재 플레이어의 최대 경험치 반환
        /// </summary>
        public float GetPlayerMaxExp()
        {
            if (spawnedPlayer != null)
            {
                return spawnedPlayer.MaxExp;
            }

            return 100f; // 기본값
        }

        /// <summary>
        /// 현재 플레이어의 경험치 진행률 반환 (0~1)
        /// </summary>
        public float GetPlayerExpProgress()
        {
            if (spawnedPlayer != null)
            {
                return spawnedPlayer.GetExpProgress();
            }

            return 0f;
        }

        /// <summary>
        /// 현재 코인 수 반환
